<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ArrowRight, Bell, CalendarDays, ChevronDown, Copy, Download, FileText, KeyRound, LifeBuoy, LoaderCircle, Monitor, RefreshCw, WalletCards, Wifi } from 'lucide-vue-next';
import { usePanelContext } from '../composables/panelContext';
import { quotaUsed, rawPeriodUsed } from '../lib/quota';
import { t } from '../i18n';
import PageHeading from '../components/PageHeading.vue';
import ConnectionGuide from '../components/member/ConnectionGuide.vue';
import UsageDetails from '../components/UsageDetails.vue';
import NodeSubscriptionCards from '../NodeSubscriptionCards.vue';
import '../styles/member-ui.css';
const route = useRoute();
const { state, site, selectedSite, busy, sub, subUser, format, subProtocol, subSource, qr, qrError, subLoading, subError, owner, publicSubPage, userStatus, subURL, bytes, date, confirmUser, loadSub, copy, downloadSub } = usePanelContext();
const connectOpen = ref(!!route.query.connect), advancedOpen = ref(false), guide = ref<HTMLElement|null>(null);
const usagePercent = computed(() => sub.value?.user.quota ? Math.min(100, Math.max(0, quotaUsed(sub.value.user) / sub.value.user.quota * 100)) : 0);
const remainingTraffic = computed(() => sub.value?.user.quota ? Math.max(0, sub.value.user.quota - quotaUsed(sub.value.user)) : null);
const remainingDays = computed(() => sub.value?.user.expires ? Math.max(0, Math.ceil((sub.value.user.expires - Date.now() / 1000) / 86400)) : null);
const queuedRemainingDays = (slot: { expires: number; paused_at: number }) => slot.expires && slot.paused_at ? Math.max(0, Math.ceil((slot.expires - slot.paused_at) / 86400)) : 0;
const queuedExpiry = (slot: { expires: number; paused_at: number }) => slot.expires ? Math.floor(Date.now() / 1000) + Math.max(0, slot.expires - slot.paused_at) : 0;
const serviceMessage = computed(() => {
  if (!sub.value) return '';
  if (sub.value.active) return sub.value.nodes.length ? t('套餐已生效，选择客户端即可开始使用。') : t('套餐已生效，连接配置正在准备。可刷新或联系管理员。');
  if (!sub.value.user.entitlement) return t('还没有可用套餐，选择套餐后即可开始连接。');
  if (!sub.value.user.enabled) return t('账户当前已停用，请联系管理员。');
  if (sub.value.user.expires && remainingDays.value === 0) return t('套餐已到期，续费或选择新套餐后恢复使用。');
  if (sub.value.user.quota && quotaUsed(sub.value.user) >= sub.value.user.quota) return t('本周期流量已用尽，请等待额度重置或查看其他套餐。');
  return t('当前服务暂不可用，请查看套餐状态或联系管理员。');
});
async function startConnection() {
  connectOpen.value = true;
  await nextTick();
  guide.value?.scrollIntoView({ block: 'start', behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
  guide.value?.focus({ preventScroll: true });
}
let connectionIntent = '';
watch([() => route.query.connect, () => route.query.client, () => route.query.platform, () => sub.value?.user.id], ([value, client, platform, id]) => {
  if (!value) { connectionIntent = ''; return; }
  const intent = [value, client, platform, id].join(':');
  if (id && intent !== connectionIntent) { connectionIntent = intent; void startConnection(); }
}, { immediate: true });
</script>
<template>
  <section v-if="state" class="member-page subscription-page">
    <PageHeading :title="owner?t('订阅管理'):t('用户中心')" :description="owner?t('套餐决定订阅内容与账号有效期。'):t('欢迎回来')+'，'+state.me.username+'。'+t('你的套餐、连接与账户服务都在这里。')" eyebrow="MY SERVICE"><template #actions><select v-if="owner" v-model="subUser" :aria-label="t('订阅成员')"><option v-for="u in state.users" :key="u.id" :value="u.id">{{u.username}}</option></select><button :disabled="subLoading" @click="loadSub(true)"><RefreshCw :size="16" :class="{spin:subLoading}"/>{{t('刷新')}}</button></template></PageHeading>
    <div v-if="owner" class="member-hint subscription-admin-filter"><label>{{t('订阅包含范围')}}<select v-model="subSource"><option v-if="!publicSubPage" value="mixed">{{t('混合订阅（优先）')}}</option><option v-if="!publicSubPage" value="local">{{t('本站本地节点')}}</option><option v-if="!publicSubPage" value="subsite">{{t('子站节点池（挂载）')}}</option><option v-if="publicSubPage" value="public">{{t('公共节点')}}</option></select></label><p>{{t('套餐决定账号额度、有效期和节点组；混合订阅按节点组过滤全部已授权来源。')}}</p></div>
    <p v-if="subError" class="error member-feedback" role="alert">{{t(subError)}}<button :disabled="subLoading" @click="loadSub(true)">{{t('重试')}}</button></p>
    <div v-if="subLoading&&!sub" class="member-empty" role="status"><LoaderCircle :size="25" class="spin"/><p>{{t('正在读取订阅节点…')}}</p></div>
    <template v-if="sub">
      <div class="service-overview">
        <article class="member-panel service-plan" :class="{'member-service-hero':!owner}">
          <header><div><span class="member-label">{{t('当前套餐')}}<template v-if="owner"> · {{sub.user.username}}</template></span><h2>{{sub.user.entitlement?.name||t('还没有开通套餐')}}</h2></div><span :class="['member-status',sub.active?'active':'failed']">{{userStatus(sub.user)}}</span></header>
          <p class="service-message">{{serviceMessage}}</p>
          <div class="service-start"><button v-if="owner||sub.active" class="primary" @click="startConnection"><Wifi :size="17"/>{{t('开始连接')}}<ArrowRight :size="17"/></button><RouterLink v-else class="member-button primary" to="/shop">{{t('选择套餐')}}<ArrowRight :size="17"/></RouterLink><button :disabled="!subURL||busy" @click="copy(subURL)"><Copy :size="16"/>{{t('复制订阅地址')}}</button></div>
          <div class="service-metrics"><div><span class="member-label">{{t('本期剩余流量')}}</span><div class="member-metric">{{!sub.user.entitlement?t('待开通'):remainingTraffic===null?t('不限量'):bytes(remainingTraffic)}}</div><p class="service-usage">{{t('已用')}} {{bytes(quotaUsed(sub.user))}} <template v-if="sub.user.quota"> / {{bytes(sub.user.quota)}}</template></p><div v-if="sub.user.quota" class="plan-progress" role="progressbar" :aria-label="t('配额用量')" :aria-valuenow="Math.round(usagePercent)" :aria-valuemin="0" :aria-valuemax="100"><span :style="{width:usagePercent+'%'}"/></div></div><div><span class="member-label">{{t('剩余有效期')}}</span><div class="member-metric">{{!sub.user.entitlement?t('待开通'):remainingDays===null?t('永久有效'):remainingDays}}<small v-if="sub.user.entitlement&&remainingDays!==null"> {{t('天')}}</small></div><p class="service-usage">{{sub.user.entitlement?(sub.user.expires?date(sub.user.expires)+' '+t('到期'):t('长期有效')):t('选择套餐后开始计算')}}</p></div></div>
          <div class="service-period"><span><CalendarDays :size="14"/>{{t('下次重置')}} · {{sub.user.meter?.end?date(sub.user.meter.end):t('不自动重置')}}</span><RouterLink v-if="!owner&&sub.user.entitlement" to="/shop">{{t('续费与更换套餐')}}<ArrowRight :size="14"/></RouterLink></div>
          <div v-if="owner&&sub.user.entitlement" class="plan-meta"><span>{{t('套餐版本')}} · v{{sub.user.entitlement.version}}</span><span>{{t('节点组')}} · {{sub.user.entitlement.group_ids.length}}</span><span>{{t('单独节点')}} · {{sub.user.entitlement.node_ids?.length||0}}</span></div>
        </article>
        <aside v-if="!owner" class="member-panel service-shortcuts"><div class="member-panel-title"><div><h2>{{t('常用服务')}}</h2><p>{{t('需要的操作，一步直达。')}}</p></div></div><nav class="service-shortcut-grid" :aria-label="t('常用服务')"><RouterLink to="/orders"><span><FileText :size="20"/></span><div><strong>{{t('我的订单')}}</strong><small>{{t('开通进度与退款')}}</small></div><ArrowRight :size="15"/></RouterLink><RouterLink to="/wallet"><span><WalletCards :size="20"/></span><div><strong>{{t('我的钱包')}}</strong><small>{{t('充值、余额与流水')}}</small></div><ArrowRight :size="15"/></RouterLink><RouterLink to="/clients"><span><Monitor :size="20"/></span><div><strong>{{t('客户端下载')}}</strong><small>{{t('按设备选择安装包')}}</small></div><ArrowRight :size="15"/></RouterLink><RouterLink to="/tickets"><span><LifeBuoy :size="20"/></span><div><strong>{{t('帮助与支持')}}</strong><small>{{t('提交问题与查看回复')}}</small></div><ArrowRight :size="15"/></RouterLink></nav><RouterLink class="service-inbox" to="/messages"><Bell :size="16"/><span>{{t('站内通知')}}</span><b v-if="state.unread_messages">{{state.unread_messages}}</b><ArrowRight :size="14"/></RouterLink></aside>
        <aside v-else class="member-panel service-connect"><span class="connect-symbol"><Wifi :size="25"/></span><h2>{{t('连接你的设备')}}</h2><p>{{t('选好客户端，复制订阅地址，即可开始连接。')}}</p><RouterLink class="member-link" to="/clients">{{t('客户端中心')}}<ArrowRight :size="15"/></RouterLink><button @click="startConnection">{{t('连接向导')}}<ArrowRight :size="15"/></button></aside>
      </div>
      <article v-if="sub.user.plan_queue?.length" class="member-panel plan-queue"><div class="member-panel-title"><div><h2>{{t('待恢复套餐')}}</h2><p>{{t('新套餐先使用，旧套餐的剩余有效期会保留。')}}</p></div><CalendarDays :size="22"/></div><ol><li v-for="(slot,index) in [...sub.user.plan_queue].reverse()" :key="slot.entitlement.revision"><span class="queue-index">{{index+1}}</span><div><strong>{{slot.entitlement.name}}</strong><p>{{index===0?t('当前套餐结束后恢复'):t('按顺序自动恢复')}}<span v-if="owner"> · {{slot.expires?date(queuedExpiry(slot)):t('不限')}}</span></p></div><span class="queue-time">{{slot.expires?queuedRemainingDays(slot):t('永久有效')}}<small v-if="slot.expires"> {{t('天可用')}}</small></span></li></ol></article>
      <section v-if="connectOpen" ref="guide" class="member-panel service-guide" tabindex="-1"><div class="member-panel-title"><div><h2>{{t('开始连接')}}</h2><p>{{t('只需三步，把服务带到你的设备。')}}</p></div><button @click="connectOpen=false">{{t('收起')}}</button></div><ConnectionGuide :key="String(route.query.client||'')+String(route.query.platform||'')" :relay-downloads="!selectedSite&&site.client_download_relay" :subscription-url="sub.url" :active="sub.active" :initial-platform="String(route.query.platform||'')" :initial-client="String(route.query.client||'')" @copy="copy"/></section>
      <details class="member-panel service-details" :open="advancedOpen" @toggle="advancedOpen=($event.target as HTMLDetailsElement).open"><summary><div><strong>{{t('订阅选项与连接详情')}}</strong><p>{{t('手动选择格式、协议，查看节点和流量明细。')}}</p></div><ChevronDown :size="18"/></summary><div class="service-details-body"><div class="subscription-layout"><div class="subscription-controls"><div class="member-tabs" role="group" :aria-label="t('订阅格式')"><button v-for="f in [{id:'mihomo',name:'Mihomo'},{id:'base64',name:'Base64'},{id:'raw',name:t('原始链接')}]" :key="f.id" :aria-pressed="format===f.id" @click="format=f.id">{{f.name}}</button></div><label>{{t('协议')}}<select v-model="subProtocol"><option value="">{{t('全部协议')}}</option><option value="vless">VLESS</option><option value="hy2">Hysteria2</option></select></label><label>{{t('订阅地址')}}<div class="copy-field"><input :value="subURL" readonly :aria-label="t('订阅地址')" @focus="($event.target as HTMLInputElement).select()"/><button class="icon" :aria-label="t('复制订阅地址')" :disabled="!subURL" @click="copy(subURL)"><Copy :size="17"/></button></div></label><div class="member-actions"><button :disabled="!sub.active||busy" @click="downloadSub"><Download :size="17"/>{{t('下载订阅')}}</button><button :disabled="!subURL" @click="copy(subURL)"><Copy :size="17"/>{{t('复制地址')}}</button></div><p class="member-label">{{(state.runtime?.mode==='no_logs'||state.runtime?.subscription_access_enabled===false)?(sub.user.last_sub?t('最近记录 ')+date(sub.user.last_sub,true)+' · ':'')+t('访问时间已停止记录'):sub.user.last_sub?t('最近访问 ')+date(sub.user.last_sub,true):t('尚未访问')}}</p></div><div class="qr-area"><img v-if="qr" :src="qr" width="200" height="200" :alt="t('当前订阅地址二维码')"/><p v-else-if="qrError" class="error" role="alert">{{qrError}}</p><LoaderCircle v-else :size="24" class="spin"/><span>{{format==='mihomo'?'Mihomo':format==='base64'?'Base64':'URI'}} · {{t('订阅')}}</span></div></div><div class="member-hint"><span>{{t('实际周期流量')}} · {{bytes(rawPeriodUsed(sub.user))}}</span></div><UsageDetails :user="sub.user"/><NodeSubscriptionCards :key="sub.user.id+':'+sub.pool+':'+subProtocol" :nodes="sub.nodes" :active="sub.active" :pool="sub.pool" :loading="subLoading" @refresh="loadSub()"/></div></details>
      <div v-if="owner" class="member-panel subscription-security"><h2>{{t('凭据管理')}}</h2><div class="member-actions"><button @click="confirmUser(sub.user,'rotate-all-sub')"><RefreshCw :size="16"/>{{t('重置订阅地址')}}</button><button class="danger-button" @click="confirmUser(sub.user,'revoke')"><KeyRound :size="16"/>{{t('撤销全部旧配置')}}</button></div></div>
    </template>
  </section>
</template>
<style scoped>
